"""Minimal RemoteSystem shim for InterOps when running outside full Squish-provided Python.

This wrapper tries to call Squish remote helper functions exposed by the
`squishtest` extension. It provides the small API surface used by
InterOps: `RemoteSystem(host, port).execute(...)`, `exists`, `upload`,
`deleteFile`, `createDirectory`, `listFiles`, and `close`.

If the Squish remote helpers are not available, the shim raises
RuntimeError with a clear message.
"""
from typing import Optional, Any, List, Tuple
import importlib
import sys, os
import logging

logger = logging.getLogger(__name__)


def _load_ext():
    # Prefer already-imported squishtest module
    try:
        import squishtest as sq
        return sq
    except Exception:
        # Try common runtime bin paths
        common = [r"C:\Program Files (x86)\squish_runtime\bin", r"C:\Program Files\squish_runtime\bin"]
        for p in common:
            if os.path.isdir(p) and p not in sys.path:
                sys.path.insert(0, p)
                try:
                    import squishtest as sq
                    return sq
                except Exception:
                    try:
                        sys.path.remove(p)
                    except Exception:
                        pass
        raise RuntimeError("squishtest extension not found; remotesystem requires Squish runtime on sys.path")


class RemoteSystem:
    def __init__(self, host: Optional[str] = None, port: Optional[int] = None):
        self._sq = _load_ext()
        # default to localhost/4322 if not provided
        self.host = host or 'localhost'
        self.port = int(port) if port is not None else 4322

    def _call(self, candidates: List[str], *args):
        for name in candidates:
            fn = getattr(self._sq, name, None)
            if fn:
                try:
                    # try with host/port first
                    return fn(self.host, self.port, *args)
                except TypeError:
                    return fn(*args)
        raise RuntimeError(f"None of remote helper names {candidates} available on squishtest module")

    def execute(self, cmd: List[str], options: Optional[dict] = None) -> Tuple[str, str, str]:
        """Execute command on remote Squish server host; returns (exitcode, stdout, stderr)"""
        candidates = ['_squish_remote_execute_command', 'remote_execute_command', 'remote_execute']
        return self._call(candidates, cmd)

    def exists(self, path: str) -> bool:
        candidates = ['_squish_remote_path_exists', 'remote_path_exists', 'path_exists']
        return bool(self._call(candidates, path))

    def upload(self, local_path: str, remote_path: str) -> bool:
        candidates = ['_squish_remote_upload_file', 'remote_upload_file', 'upload_file']
        return bool(self._call(candidates, local_path, remote_path))

    def deleteFile(self, remote_path: str) -> bool:
        candidates = ['_squish_remote_delete_file', 'remote_delete_file', 'delete_file']
        return bool(self._call(candidates, remote_path))

    def createDirectory(self, remote_path: str) -> bool:
        candidates = ['_squish_remote_create_path', 'remote_create_path', 'create_directory']
        return bool(self._call(candidates, remote_path))

    def listFiles(self, remote_path: str) -> List[str]:
        candidates = ['_squish_remote_list_files', 'remote_list_files', 'list_files']
        res = self._call(candidates, remote_path)
        if res is None:
            return []
        if isinstance(res, str):
            return [l for l in res.splitlines() if l]
        return list(res)

    def close(self):
        # no-op; keep for compatibility
        return
